import datetime
import re

from ta_moler.events.rtg_ctrl.genericrtg_ctrl_lineevent import GenericRtgCtrlLineEvent


class StoppingSession(GenericRtgCtrlLineEvent):
    """Stopping session event class."""

    # Example line:          Stopping Session c2 of user toor4nsn.
    re_stopping_session = re.compile(r"Stopping Session c(?P<NUMBER>\d+) of user (?P<USER>.*)\.")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for stopping session.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(StoppingSession, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self.re_stopping_session], match="any"
        )


